const icon=n=>n==='trophy'?'<svg class="arena-trophy-3d" viewBox="0 0 48 48" aria-hidden="true"><defs><linearGradient id="arena-trophy-metal" x1="0" x2=".9" y1="0" y2="1"><stop stop-color="#fff8d8"/><stop offset=".23" stop-color="#f4d38e"/><stop offset=".49" stop-color="#b98530"/><stop offset=".78" stop-color="#efc975"/><stop offset="1" stop-color="#83551e"/></linearGradient></defs><path d="M15 6H5v9c0 8 5 12 14 12M33 6h10v9c0 8-5 12-14 12" fill="none" stroke="#d8a950" stroke-width="3"/><path d="M13 3h22v13c0 10-6 16-11 17-5-1-11-7-11-17zM21 33h6v7h6v4H15v-4h6z" fill="url(#arena-trophy-metal)" stroke="#865d28" stroke-width="1.2"/><path d="M18 7v12c0 5 3 9 6 10M18 41h12" fill="none" stroke="#fff8d6" stroke-width="2" opacity=".83"/></svg>':`<svg class="arena-menu-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.play}</svg>`;
