let lastStatePoll=0,statePollPending=false,liveRequested=false,liveTimer=null,liveChannel=null,boardChannel=null,boardChannelUser=null;
function requestLiveState(){if(!online)return;liveRequested=true;if(liveTimer!==null)return;liveTimer=setTimeout(()=>{liveTimer=null;pollOnlineState(true);},Math.max(0,100-(Date.now()-lastStatePoll)));}
function disconnectBoardStream(){if(boardChannel)client?.removeChannel(boardChannel);boardChannel=null;boardChannelUser=null;liveBoardSync.reset(null);}
async function connectLiveState(){
 if(!client)return;
 if(!liveChannel)liveChannel=client.channel('arena-live-v1').on('broadcast',{event:'revision'},()=>requestLiveState()).subscribe(status=>{if(status==='SUBSCRIBED')requestLiveState();});
 const user=session?.user?.id;if(!user)return;
 try{await client.realtime.setAuth(session.access_token);}catch{return;}
 if(session?.user?.id!==user||boardChannelUser===user)return;
 disconnectBoardStream();boardChannelUser=user;liveBoardSync.reset(user);
 boardChannel=client.channel('arena-board:'+user,{config:{private:true}}).on('broadcast',{event:'board'},message=>{
  if(!online||session?.user?.id!==user)return;
  if(liveBoardSync.receive(message.payload,state,user)&&tab==='board'&&!practice){render();updateClocks();}
  requestLiveState();
 }).subscribe(status=>{if(status==='SUBSCRIBED')requestLiveState();});
}
async function pollOnlineState(force=false){if(!online||document.hidden||busy||statePollPending)return;const fast=tab==='board'&&!practice&&state.games.some(g=>g.id===gameId&&['pending','playing'].includes(g.status));if(!force&&Date.now()-lastStatePoll<(fast?250:1800))return;liveRequested=false;lastStatePoll=Date.now();statePollPending=true;try{if(Date.now()-lastPresence>30000){lastPresence=Date.now();api({id:crypto.randomUUID(),type:'presence',payload:{}}).catch(()=>{});}const result=await api();liveBoardSync.reconcile(result.state,result.revision,result.actor?.id||null);if(busy||($('#modal').open&&$('#modal').dataset.match!=='true'))return;if(!result.actor){session=null;online=false;state=result.state;render();return;}const old=JSON.stringify(state);const oldSocial=socialCount(state,actor.id);if(socialCount(result.state,actor.id)>oldSocial)toast('Novo convite ou solicitação de amizade. Abra Jogadores.');const added=result.state.tournaments.filter(t=>!state.tournaments.some(old=>old.id===t.id));if(added.length)toast(`${added.length} novo${added.length>1?'s campeonatos':' campeonato'} ${added.length>1?'disponíveis':'disponível'}. Confira Torneios.`);state=result.state;actor=result.actor;syncMatchDialog();if(JSON.stringify(state)!==old)render();const g=state.games.find(g=>g.id===gameId);if(tab==='board'&&!practice&&g?.status==='playing'){const color=new Chess(g.fen).turn();if(g[color==='w'?'whiteMs':'blackMs']-(Date.now()-g.lastMoveAt)<=0)await send('timeout',{id:g.id});}}catch{}finally{statePollPending=false;if(liveRequested)requestLiveState();}}
setInterval(()=>pollOnlineState(liveRequested),250);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)requestLiveState();});
async function enterOnline(currentSession,displayName){session=currentSession;online=true;connectLiveState();const result=await api();state=result.state;actor=result.actor;if(!state.players[actor.id])await send('register',{name:displayName||session.user?.user_metadata?.display_name||'Jogador'});render();}
async function connectFinance(){try{const endpoint=(config.supabaseUrl||'https://kjqovtvhgulwufdzfmif.supabase.co')+'/functions/v1/arena-finance';const response=await fetch(endpoint+'?action=health&forceFunctionRegion=us-west-2',{signal:AbortSignal.timeout(5000)});if(!response.ok)return;const health=await response.json();if(health.service!=='arena-finance')return;config.financeEndpoint=endpoint;config.identityConfigured=health.trustConfigured;config.paymentsEnabled=health.paymentsEnabled;config.cashGamesEnabled=health.gamesEnabled;config.paymentEnvironment=health.environment;}catch{}}
async function boot(){const recoveryLink=new URLSearchParams(location.hash.slice(1)).get('type')==='recovery';const route=location.hash.slice(1);if(['lobby','tournaments','wallet','fairplay','ranking','community','my-games','learn','shop','finance'].includes(route))tab=route;loadDemo();try{config=await fetch('/api/index?action=config').then(r=>r.json());await connectFinance();if(config.configured){client=createClient(config.supabaseUrl,config.publishableKey);session=(await client.auth.getSession()).data.session;if(session)await enterOnline(session);else state=(await api()).state;client.auth.onAuthStateChange((event,newSession)=>{if(event==='PASSWORD_RECOVERY'&&newSession){session=newSession;setTimeout(resetPasswordForm,0);}if(['SIGNED_IN','TOKEN_REFRESHED'].includes(event)&&newSession){session=newSession;setTimeout(()=>enterOnline(newSession).catch(()=>toast('Não foi possível carregar sua conta. Tente entrar novamente.')),0);}if(event==='SIGNED_OUT'){disconnectBoardStream();session=null;loadDemo();api().then(r=>{state=r.state;render();}).catch(()=>render());}});}}catch{}render();if(recoveryLink&&session)resetPasswordForm();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});}
trust.startSignals();boot();

