document.addEventListener('change',async e=>{if(e.target.name==='cover'){const path=$('#tournament-form [name=coverPath]');if(path)path.value='';const preview=$('#tournament-cover-preview');if(preview)preview.hidden=true;}if(e.target.id!=='tournament-cover-file')return;const f=$('#tournament-form'),button=f.querySelector('[type=submit]'),status=$('#tournament-cover-status');button.disabled=true;try{if(!online)throw Error('Entre com a conta administrativa para enviar uma capa.');const file=e.target.files[0];if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024)throw Error('Escolha JPEG, PNG ou WebP de até 5 MB.');status.textContent='Preparando capa…';const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas'),scale=Math.min(1,512/Math.max(bitmap.width,bitmap.height));canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();let quality=.85,image=canvas.toDataURL('image/jpeg',quality);while(image.length>43000&&quality>.2){quality-=.1;image=canvas.toDataURL('image/jpeg',quality);}if(image.length>43000)throw Error('Escolha uma imagem menos detalhada.');const result=await trustRequest('tournament-cover',{image});f.querySelector('[name=coverPath]').value=result.coverPath;const preview=$('#tournament-cover-preview');preview.src=image;preview.hidden=false;status.textContent='Capa enviada. Será publicada ao criar o torneio.';}catch(error){status.textContent=error.message;}finally{button.disabled=false;}});

