let heroPointerFrame=0;
document.addEventListener('pointermove',event=>{
 const hero=event.target.closest?.('.hero');if(!hero||window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)return;
 const {clientX:x,clientY:y}=event;if(heroPointerFrame)cancelAnimationFrame(heroPointerFrame);
 heroPointerFrame=requestAnimationFrame(()=>{const r=hero.getBoundingClientRect(),px=(x-r.left)/r.width-.5,py=(y-r.top)/r.height-.5;hero.style.setProperty('--hero-x',(px*7).toFixed(2)+'deg');hero.style.setProperty('--hero-y',(-py*5).toFixed(2)+'deg');hero.style.setProperty('--hero-light',(50+px*35).toFixed(1)+'%');heroPointerFrame=0;});
},{passive:true});

function updateComputerOpponent(form){
 if(!form||form.id!=='quick-form')return;
 const computer=form.querySelector('[name=opponent]')?.value==='sandra',paid=form.querySelector('[name=mode]')?.value==='stake';
 const consent=form.querySelector('#computer-consent'),checkbox=form.querySelector('[name=botConsent]'),limit=form.querySelector('#computer-entry-limit'),stake=form.querySelector('[name=stake]'),rated=form.querySelector('[name=rated]');
 if(consent)consent.hidden=!computer;if(checkbox){checkbox.required=computer;checkbox.disabled=!computer;}
 if(limit)limit.hidden=!(computer&&paid);
 if(rated){rated.disabled=computer;if(computer)rated.checked=false;}
 if(stake){const max=computer?computerOffer.maxStakeCents:100000;stake.max=(max/100).toFixed(2);if(computer&&Number(stake.value)*100>max)stake.value=(max/100).toFixed(2);}
 updateEntryPreview(form);
}
